extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve caricarsi senza errori"):
		return

	var coins_array = get_prop(main, "coins")
	if not check("coins_prop", typeof(coins_array) == TYPE_ARRAY, "coin_manager.gd deve avere l'Array coins"):
		return

	await wait_frames(5)

	check("all_cleaned", coins_array.size() == 0, "Tutte le monete con y > 500.0 devono essere rimosse dall'Array coins")
	check("no_errors", errors_text() == "", "L'eliminazione non deve causare errori nel Debugger")

